// Combine all and format into objects
const allFlashcards = [];

function mapToObj(arr) {
    const uniqueItems = [...new Map(arr.map(item => [JSON.stringify(item), item])).values()];
    return uniqueItems.map(item => ({
        sisi_depan: item[0],
        sisi_belakang_kana: item[0],
        sisi_belakang_romaji: item[1],
        arti_indonesia: item[2],
        kategori: item[3],
        contoh_kalimat: item[4]
    }));
}

const verbsObj = mapToObj(rawVerbs);
const nounsObj = mapToObj(rawNouns);
const adjObj = mapToObj(rawAdjectives);

